<script lang="ts">
import {onMount,untrack,tick} from 'svelte';import type {WebhookConfig,NamedValue} from './notifications';import {notificationError} from './notifications';import {notificationAction} from './bridge';import WebhookRows from './WebhookRows.svelte';import Choice from './Choice.svelte';import Icon from './Icon.svelte';
let {config,t,profile,province,language,onclose,ondone}:{config:WebhookConfig;t:(key:string)=>string;profile:string;province:string;language:string;onclose:()=>void;ondone:(value:WebhookConfig)=>void}=$props();
let draft=$state(untrack(()=>structuredClone($state.snapshot(config))));const blank=():NamedValue=>({name:'',value:'',secret:true});let headers=$state(untrack(()=>draft.headers.length?draft.headers:[blank()]));let query=$state(untrack(()=>draft.query.length?draft.query:[blank()]));let dialog:HTMLDialogElement;let schema=$state(false);let busy=$state(false);let error=$state('');let tested=$state('idle');let testDetail=$state('');let textarea=$state<HTMLTextAreaElement>();
function value():WebhookConfig{return {...$state.snapshot(draft),headers:$state.snapshot(headers).filter(row=>row.name||row.value).map(row=>({...row,name:row.name.trim()})),query:$state.snapshot(query).filter(row=>row.name||row.value).map(row=>({...row,name:row.name.trim()}))};}
function sizeText(){if(textarea){textarea.style.height='auto';textarea.style.height=textarea.scrollHeight+'px';}}
onMount(()=>{dialog.showModal();dialog.querySelector<HTMLInputElement>('input')?.focus();sizeText();return()=>dialog.close();});
async function done(){busy=true;error='';try{const next=value();await notificationAction({action:'validate_webhook',config:next});ondone(next);}catch(reason){error=notificationError(reason,t);}finally{busy=false;}}
async function test(){tested='busy';try{const result=await notificationAction<{status:number;elapsed_ms:number}>({action:'webhook_test',config:value(),profile,province,language});tested='ok';testDetail=`HTTP ${result.status} · ${result.elapsed_ms} ms`;}catch(reason){tested='error';testDetail=notificationError(reason,t);}}
</script>
<dialog class="profile-editor webhook-dialog" bind:this={dialog} oncancel={event=>{event.preventDefault();if(!busy)onclose();}}><form onsubmit={event=>{event.preventDefault();void done();}}><h1>{t('Дополнительные параметры')}</h1><div class="editor-scroll"><WebhookRows title={t('Заголовки')} bind:rows={headers} {t}/><p class="muted compact-hint">{t('Все значения скрыты по умолчанию. Замок снимает скрытие. Значения заголовков не включаются в диагностику.')}</p><WebhookRows title={t('Параметры URL')} bind:rows={query} {t}/><div class="webhook-request-body">{#if draft.method==='POST'}<div class="webhook-body-mode"><Choice label={t('Тело запроса')} icon={null} bind:value={draft.body_mode} options={[{value:'standard',label:t('Стандартный JSON')},{value:'custom',label:t('Свой JSON')}]} onchange={()=>{if(draft.body_mode==='custom'&&!draft.body)draft.body=JSON.stringify({text:'{{message}}'},null,2);void tick().then(sizeText);}}/></div>{#if draft.body_mode==='custom'}<textarea class="custom-json" aria-label={t('Свой JSON')} rows="5" bind:this={textarea} bind:value={draft.body} oninput={sizeText} spellcheck="false"></textarea><small class="muted compact-hint">{t('Переменные: {{message}}, {{event}}, {{profile}}, {{province}}, {{timestamp}}, {{event_id}}')}</small>{:else}<button type="button" class="disclosure" aria-expanded={schema} onclick={()=>schema=!schema}>{schema?'▾':'▸'} {t('Показать схему JSON')}</button>{#if schema}<pre class="json-schema">{JSON.stringify({schema_version:1,event_id:'…',event:'test',timestamp:'…',profile:'…',province:'…',action_required:false,message:'…'},null,2)}</pre>{/if}{/if}{/if}</div><p class="muted compact-hint">{t('Таймаут: 10 с. Ограниченные повторы при сетевых ошибках, 429 и 5xx.')}</p>{#if error}<p role="alert" class="notification-error">{error}</p>{/if}</div><div class="editor-actions split-actions"><button type="button" disabled={tested==='busy'} title={testDetail||t('Тест')} onclick={()=>void test()}><Icon name={tested==='ok'?'check':tested==='error'?'alert':tested==='busy'?'clock':'test'}/>{t('Тест')}</button><span></span><button type="button" disabled={busy} onclick={onclose}>{t('Отмена')}</button><button type="submit" class="primary" disabled={busy}><Icon name="check"/>{t('Готово')}</button></div></form></dialog>
